let active=null;
export function confirmAction({title='Подтвердить действие',name='',description='',detail='',confirmLabel='Подтвердить'}={}){
 if(active)return Promise.resolve(false);
 const trigger=document.activeElement;
 active=new Promise(resolve=>{const d=document.createElement('dialog');d.className='vmet-confirm-dialog';d.setAttribute('role','alertdialog');d.setAttribute('aria-labelledby','vmet-confirm-title');d.setAttribute('aria-describedby','vmet-confirm-description');const top=document.createElement('div');top.className='vmet-confirm-heading';const h=document.createElement('h2');h.id='vmet-confirm-title';h.textContent=title;const close=document.createElement('button');close.type='button';close.className='vmet-confirm-close';close.textContent='×';close.setAttribute('aria-label','Закрыть окно');top.append(h,close);d.append(top);if(name){const file=document.createElement('p');file.className='vmet-confirm-filename';file.textContent=name;d.append(file)}const text=document.createElement('p');text.id='vmet-confirm-description';text.textContent=description;d.append(text);if(detail){const note=document.createElement('p');note.className='vmet-confirm-detail';note.textContent=detail;d.append(note)}const actions=document.createElement('div');actions.className='vmet-confirm-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='vmet-confirm-cancel';cancel.textContent='Отмена';cancel.autofocus=true;const accept=document.createElement('button');accept.type='button';accept.className='vmet-confirm-accept';accept.textContent=confirmLabel;actions.append(cancel,accept);d.append(actions);document.body.append(d);let accepted=false;close.onclick=cancel.onclick=()=>d.close();accept.onclick=()=>{accepted=true;d.close()};d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()});d.addEventListener('close',()=>{d.remove();active=null;if(trigger?.isConnected)trigger.focus();resolve(accepted)},{once:true});d.showModal();cancel.focus()});return active;
}

